{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "The highest-transfer analogue, GSK1322322, has absolute oral bioavailability of 77% in healthy volunteers in the fed state (57% fasted), directly showing that a large, lipophilic, heteroaromatic molecule with many H-bond acceptors can achieve high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Deucravacitinib, a high-transfer heteroaromatic amide-containing analogue, has 99% absolute oral bioavailability in healthy subjects, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Brepocitinib, another high-transfer analogue, has 75% absolute oral bioavailability in humans, supporting high F for a nitrogen-rich kinase-inhibitor-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "R406, a pyrimidine-aminophenyl amide analogue, has 54.6% oral bioavailability in humans, supporting high F despite substantial molecular complexity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "ZL-2201, a related pyrimidine/azole kinase inhibitor, is predicted to have approximately 70% oral bioavailability in humans at low dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Silodosin, a larger polar molecule, has 32.2% absolute oral bioavailability in healthy adults, still above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Nilotinib, a solubility-limited lipophilic kinase inhibitor, has about 31% absolute oral bioavailability under fasted conditions, supporting high F at the threshold despite solubility concerns.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Isradipine, a dihydropyridine with extensive first-pass metabolism, has only 16.5% systemic availability, providing the main contradictory evidence; however, its structural class and metabolic liability are not representative of the query's kinase-inhibitor-like scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High is predicted. Multiple high-transfer experimental analogues with large, lipophilic, heteroaromatic scaffolds and amide/amine functionality show absolute oral bioavailability well above 20% (54–99%), and even borderline analogues such as nilotinib and silodosin are around 30%. The physicochemical prior is low, but direct experimental evidence overrides it. The only clearly low analogue, isradipine, is a dihydropyridine with a distinct first-pass liability and lower structural relevance to the query.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule.",
    "Unknown impact of the isopropyl ester (possible hydrolysis) and acrylamide reactivity on first-pass stability.",
    "No data on solubility, dissolution, or food effect for the query; high logP and TPSA may still limit absorption in some conditions.",
    "Conflicting borderline evidence from nilotinib at higher doses (16%) and isradipine (17%) leaves some uncertainty."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C39"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "high-F large heteroaromatic analogues"
    }
  ],
  "revision_action": "initial"
}

